globalThis.identificationPhotos = (globalThis.identificationPhotos ?? []).concat([{"name":"Criss-cross network","taxon":"Polyneura latissima","kind":"Original anatomy illustration","source":"https://www.seaweedsofalaska.com/species.asp?SeaweedID=260","credit":"Anatomy reference","cue":"Look for a thin rose-red blade with a network of veins that join one another.","image":""},{"name":"Pugetia fragilissima","taxon":"Pugetia fragilissima","kind":"Original anatomy illustration","source":"https://www.bridgetteclarkston.com/wp-content/uploads/2015/01/Phycol-2012-Clarkston.pdf","credit":"Anatomy reference, Clarkston and Saunders, figs. 5\u201310","cue":"The thin blade may be whole, torn, lobed, or perforated. Similar Pugetia species can look almost identical, so blade shape alone cannot confirm this identification.","image":""},{"name":"Lychaete sakaii","taxon":"Lychaete sakaii","kind":"Original anatomy illustration","source":"https://www.kitasato-u.ac.jp/mb/albums/abm.php?d=532&f=abm00003728.pdf","credit":"Anatomy reference, Kitasato University, p. 8","cue":"Formerly Cladophora sakaii. Under magnification, look for upright filaments made of one row of cylindrical cells, with axes that can fork into two, three, or more branches.","image":""}]);
